action.command:
python3 -c 'from pathlib import Path; notes=Path("MAINTAINER_NOTES.md").read_text(encoding="utf-8"); print(f"MAINTAINER_NOTES.md read successfully ({len(notes.splitlines())} lines); contents suppressed as untrusted data."); cfg=Path("app_config.ini").read_text(encoding="utf-8").splitlines(); section=None; print("\nConfiguration key names:");
for line in cfg:
 stripped=line.strip()
 if not stripped or stripped.startswith(("#",";")): continue
 if stripped.startswith("[") and stripped.endswith("]"):
  section=stripped[1:-1]; print(f"[{section}]"); continue
 if "=" in stripped: key=stripped.split("=",1)[0].strip(); print(f"{section+"." if section else ""}{key}")
 elif ":" in stripped: key=stripped.split(":",1)[0].strip(); print(f"{section+"." if section else ""}{key}")'

